using EventLensAI.Domain.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace EventLensAI.Infrastructure.Persistence.Configurations;
internal sealed class EventQRCodeConfiguration:IEntityTypeConfiguration<EventQRCode>{public void Configure(EntityTypeBuilder<EventQRCode>b){b.ToTable("event_qr_codes");b.ConfigureBase();b.Property(x=>x.QRType).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.Token).HasMaxLength(100);b.Property(x=>x.PublicUrl).HasMaxLength(1000);b.Property(x=>x.ImageStoragePath).HasMaxLength(1000);b.Property(x=>x.CustomizationJson).HasColumnType("nvarchar(max)");b.HasIndex(x=>x.Token).IsUnique();b.HasIndex(x=>x.EventId);b.HasOne(x=>x.Event).WithMany().HasForeignKey(x=>x.EventId).OnDelete(DeleteBehavior.NoAction);}}
internal sealed class EventAccessConfigurationConfiguration:IEntityTypeConfiguration<EventAccessConfiguration>{public void Configure(EntityTypeBuilder<EventAccessConfiguration>b){b.ToTable("event_access_configurations");b.ConfigureBase();b.Property(x=>x.PasswordHash).HasMaxLength(500);b.HasIndex(x=>x.EventId).IsUnique();b.HasOne(x=>x.Event).WithOne().HasForeignKey<EventAccessConfiguration>(x=>x.EventId).OnDelete(DeleteBehavior.NoAction);}}
internal sealed class GuestSessionConfiguration:IEntityTypeConfiguration<GuestSession>{public void Configure(EntityTypeBuilder<GuestSession>b){b.ToTable("guest_sessions");b.ConfigureBase();b.Property(x=>x.SessionToken).HasMaxLength(100);b.Property(x=>x.IPAddress).HasMaxLength(100);b.Property(x=>x.DeviceInfo).HasMaxLength(1000);b.HasIndex(x=>x.SessionToken).IsUnique();b.HasIndex(x=>x.EventId);b.HasOne(x=>x.Event).WithMany().HasForeignKey(x=>x.EventId).OnDelete(DeleteBehavior.NoAction);}}
internal sealed class EventAccessLogConfiguration:IEntityTypeConfiguration<EventAccessLog>{public void Configure(EntityTypeBuilder<EventAccessLog>b){b.ToTable("event_access_logs");b.ConfigureBase();b.Property(x=>x.Action).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.DeviceType).HasMaxLength(100);b.HasIndex(x=>x.EventId);b.HasIndex(x=>x.Timestamp);b.HasOne<Event>().WithMany().HasForeignKey(x=>x.EventId).OnDelete(DeleteBehavior.NoAction);b.HasOne<EventQRCode>().WithMany().HasForeignKey(x=>x.QRCodeId).OnDelete(DeleteBehavior.NoAction);b.HasOne<GuestSession>().WithMany().HasForeignKey(x=>x.GuestSessionId).OnDelete(DeleteBehavior.NoAction);}}
